  ChevronRightIcon,
  XMarkIcon,
} from "@heroicons/react/24/outline";
import AdminSidebar from "../AdminSidebar";
import { getAllReports, updateReportStatus, notifyUser } from "../../../services/api";

export default function UserReports() {
  const [selectedReport, setSelectedReport] = useState(null);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [search, setSearch] = useState("");
  const [reports, setReports] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showHistory, setShowHistory] = useState(false);
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    resolved: 0,
    thisWeek: 0
  });

  useEffect(() => {
    fetchReports();
  }, []);

  const fetchReports = async () => {
    try {
      setIsLoading(true);
      const response = await getAllReports();
      setReports(response);
      
      const pending = response.filter(r => r.status === 'pending' || !r.status).length;
      const resolved = response.filter(r => r.status === 'resolved').length;
      const oneWeekAgo = new Date();
      oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
      const thisWeek = response.filter(r => new Date(r.created_at) > oneWeekAgo).length;

      setStats({
        total: response.length,
        pending,
        resolved,
        thisWeek
      });
    } catch (error) {
      console.error('Error fetching reports:', error);
      setReports([]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleViewDetails = (report) => {
    setSelectedReport(report);
    setShowDetailModal(true);
  };

  const handleResolveReport = async (reportId, resolution) => {
    try {
      await updateReportStatus(reportId, {
        status: resolution,
        resolvedAt: new Date().toISOString()
      });

      if (selectedReport?.reporter_id) {
        await notifyUser(selectedReport.reporter_id, {
          type: 'report_resolved',
          message: `Your report has been reviewed and marked as ${resolution}.`
        });
      }

      if (resolution !== 'invalid' && selectedReport?.reported_user_id) {
        await notifyUser(selectedReport.reported_user_id, {
          type: resolution,
          message: `Your account action: ${resolution}`
        });
      }

      setShowDetailModal(false);
      await fetchReports();
      alert(`Report has been marked as ${resolution}`);
    } catch (error) {
      console.error('Error resolving report:', error);
      alert('Failed to resolve report.');
    }
  };

  const getStatusBadgeClass = (status) => {
    switch(status) {
      case 'pending':
        return 'bg-yellow-100 text-yellow-600';
      case 'resolved':
        return 'bg-green-100 text-green-600';
      case 'suspended':
        return 'bg-red-100 text-red-600';
      case 'invalid':
        return 'bg-gray-100 text-gray-600';
      default:
        return 'bg-gray-100 text-gray-600';
    }
  };

  const filteredReports = reports.filter(report => 
    (report.reported_user_name?.toLowerCase().includes(search.toLowerCase()) ||
    report.reporter_name?.toLowerCase().includes(search.toLowerCase()) ||
    report.reason?.toLowerCase().includes(search.toLowerCase()))
    &&
    (showHistory 
      ? report.status !== 'pending' 
      : report.status === 'pending' || !report.status)
  );

  return (
    <div className="flex h-screen bg-gradient-to-br from-gray-50 to-white">
      {/* Sidebar */}
      <AdminSidebar />

      {/* Main Content */}
      <div className="flex-1 overflow-hidden flex flex-col">
        {/* Header */}
        <div className="bg-white border-b shadow-sm">
          <div className="flex items-center justify-between px-8 py-6">
            <h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">
              User Reports
            </h2>
            <div className="flex items-center space-x-4">
              <div className="w-10 h-10 bg-gradient-to-r from-blue-500 to-indigo-500 rounded-full flex items-center justify-center text-white font-semibold">
                AD
              </div>
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-8">
          {/* Stats */}
          <div className="grid grid-cols-4 gap-4 mb-6">
            <div className="bg-white p-4 rounded-xl text-center border border-gray-100">
              <p className="text-2xl font-bold text-blue-600">{stats.total}</p>
              <p className="text-gray-500 text-sm">Total Reports</p>
            </div>
            <div className="bg-white p-4 rounded-xl text-center border border-gray-100">
              <p className="text-2xl font-bold text-yellow-600">{stats.pending}</p>
              <p className="text-gray-500 text-sm">Pending</p>
            </div>
            <div className="bg-white p-4 rounded-xl text-center border border-gray-100">
              <p className="text-2xl font-bold text-green-600">{stats.resolved}</p>
              <p className="text-gray-500 text-sm">Resolved</p>
            </div>
            <div className="bg-white p-4 rounded-xl text-center border border-gray-100">
              <p className="text-2xl font-bold text-purple-600">{stats.thisWeek}</p>
              <p className="text-gray-500 text-sm">This Week</p>
            </div>
          </div>

          {/* Filter & Search */}
          <div className="flex justify-between items-center mb-4">
            <div className="relative w-64">
              <MagnifyingGlassIcon className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search reports..."
                className="pl-10 pr-3 py-2 w-full border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500/20"
              />
            </div>
            <button
              onClick={() => setShowHistory(!showHistory)}
              className={`flex items-center px-4 py-2 rounded-lg transition-colors ${
                showHistory 
                  ? 'bg-blue-100 text-blue-600' 
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              <ClockIcon className="w-5 h-5 mr-2" />
              {showHistory ? 'Pending Reports' : 'History'}
            </button>
          </div>

          {/* Reports Table */}
          <div className="overflow-x-auto bg-white rounded-2xl shadow-sm border border-gray-100">
            {isLoading ? (
              <div className="text-center py-8">Loading reports...</div>
            ) : filteredReports.length === 0 ? (
              <div className="text-center py-12 text-gray-500">
                <p className="text-lg font-medium">No reports found</p>
              </div>
            ) : (
              <table className="w-full text-sm">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-6 py-3 text-left text-gray-600 font-medium">Reported User</th>
                    <th className="px-6 py-3 text-left text-gray-600 font-medium">Reporter</th>
                    <th className="px-6 py-3 text-left text-gray-600 font-medium">Reason</th>
                    <th className="px-6 py-3 text-left text-gray-600 font-medium">Date</th>
                    <th className="px-6 py-3 text-left text-gray-600 font-medium">Status</th>
                    <th className="px-6 py-3 text-left text-gray-600 font-medium">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {filteredReports.map((report) => (
                    <tr key={report.id} className="hover:bg-gray-50">
                      <td className="px-6 py-4">
                        <p className="font-medium text-gray-900">{report.reported_user_name}</p>
                      </td>
                      <td className="px-6 py-4 text-gray-600">{report.reporter_name}</td>
                      <td className="px-6 py-4 text-gray-600">{report.reason}</td>
                      <td className="px-6 py-4 text-gray-600">
                        {new Date(report.created_at).toLocaleDateString()}
                      </td>
                      <td className="px-6 py-4">
                        <span className={`px-3 py-1 rounded-full text-xs font-medium ${getStatusBadgeClass(report.status)}`}>
                          {report.status || 'pending'}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <button 
                          onClick={() => handleViewDetails(report)}
                          className="text-blue-600 hover:text-blue-700 font-medium"
                        >
                          View Details
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>

      {/* Report Detail Modal */}
      {showDetailModal && selectedReport && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-2xl w-full">
            <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-6 flex items-center justify-between rounded-t-2xl">
              <h3 className="text-xl font-bold text-white">Report Details</h3>
              <button
                onClick={() => setShowDetailModal(false)}
                className="text-white hover:bg-white/20 p-2 rounded-lg transition-colors"
              >
                <XMarkIcon className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6">
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <h4 className="font-medium text-gray-700 mb-1">Reporter</h4>
                    <p className="text-gray-900">{selectedReport.reporter_name}</p>
                    <p className="text-sm text-gray-500">ID: {selectedReport.reporter_id}</p>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <h4 className="font-medium text-gray-700 mb-1">Reported User</h4>
                    <p className="text-gray-900">{selectedReport.reported_user_name}</p>
                    <p className="text-sm text-gray-500">ID: {selectedReport.reported_user_id}</p>
                  </div>
                </div>

                <div className="bg-gray-50 p-4 rounded-lg">
                  <h4 className="font-medium text-gray-700 mb-2">Report Reason</h4>
                  <p className="text-gray-900">{selectedReport.reason}</p>
                  {selectedReport.description && (
                    <p className="text-gray-600 text-sm mt-2">{selectedReport.description}</p>
                  )}
                </div>
              </div>

              {selectedReport.status === 'pending' && (
                <div className="flex space-x-4 mt-6">
                  <button
                    onClick={() => handleResolveReport(selectedReport.id, 'warning')}
                    className="flex-1 bg-yellow-500 text-white py-2 rounded-lg hover:bg-yellow-600 transition-colors font-medium"
                  >
                    Issue Warning
                  </button>
                  <button
                    onClick={() => handleResolveReport(selectedReport.id, 'suspended')}
                    className="flex-1 bg-red-500 text-white py-2 rounded-lg hover:bg-red-600 transition-colors font-medium"
                  >
                    Suspend User
                  </button>
                  <button
                    onClick={() => handleResolveReport(selectedReport.id, 'invalid')}
                    className="flex-1 bg-gray-500 text-white py-2 rounded-lg hover:bg-gray-600 transition-colors font-medium"
                  >
                    Mark Invalid
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
